 * match the surrounding text color and, through it, the active
 * --heading-color / --text-color / --primary theme variables - no
 * separate icon color system to keep in sync.
 *
 * USAGE
 *   <?php echo mh_icon('calendar'); ?>
 *   <?php echo mh_icon('trash', 'mh-icon-danger'); ?>
 *
 * Every icon renders as:
 *   <svg class="mh-icon [extra classes]" viewBox="0 0 24 24" ...>...</svg>
 * Sizing/color is controlled entirely by CSS (see .mh-icon in
 * admin_theme.css) - font-size sets the size, color sets the stroke.
 */

